"""Wave 43: deeper profile-only reviews for Abigail Johnson and Michal Strnad. No rubric."""
import json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
P={};R={}
def r(text,source,url,date,kind='Reported evidence',access='Page text reviewed'):
 return dict(text=text,source=source,url=url,date=date,kind=kind,access=access)
def add(id,status,summary,mechanism,period,support,counter,limitations,confidence='Low / narrow review'):
 P[id]=dict(status=status,reviewedAt='2026-10-30',reviewDepth='Narrow source-led review under a limited search budget; not independently editorially reviewed; no rubric assigned',confidence=confidence,period=period,summary=summary,mechanism=mechanism,support=support,counter=counter,limitations=limitations)

DOL='https://www.dol.gov/agencies/ebsa/employers-and-advisers/plan-administration-and-compliance/compliance-assistance-releases/2025-01'
add('abigail-johnson','mixed',
 'Johnson is chair and CEO of Fidelity. The reviewed primary record is the Labor Department release of 28 May 2025 rescinding its March 2022 guidance on cryptocurrency in 401(k) plans; it names no firm and gives a general, stated rationale. Fidelity had publicly offered a bitcoin option in 401(k) plans in 2022 and was criticised by senators; that earlier material is in the prior profile and was not re-opened here. The reviewed pages do not show that Johnson personally sought or received the policy change, or any firm-specific benefit. A sector-wide rule change is not a personal exchange. No rubric: leverage, benefit and exchange are not each supported by opened receipts.',
 'Industry-level regulatory guidance affecting a product Fidelity offers; personal intervention and firm-specific benefit not established',
 'Labor Department guidance March 2022 and May 2025',
 [r('EBSA Compliance Assistance Release 2025-01 (28 May 2025) rescinds CAR 2022-01 (10 March 2022) "in full". Stated rationale: the "extreme care" standard is not found in ERISA; the Department restores a neutral stance that neither endorses nor disapproves fiduciaries who include cryptocurrency, and fiduciary decisions are context specific, citing Fifth Third v. Dudenhoeffer. The release names no company.','US Department of Labor, EBSA',DOL,'2025-05-28','Primary regulatory action (general guidance)','Page text reviewed'),
  r('Role-only receipt: Johnson is Fidelity chair and CEO (existing profile; the prior profile cites an Axios report that the April 2022 Fidelity challenge to the 2022 guidance was attributed to executive Dave Gray, and a July 2022 senators\' letter to Johnson). Neither was re-opened in this wave (Axios returned HTTP 403).','Existing profile in data/assessments.json',DOL,'2022','Role and prior-profile context; not independently re-verified','Not re-opened')],
 [r('The release is general guidance, names no provider, restores a neutral stance and gives a legal rationale; commentators in search results noted it is not an endorsement and creates no safe harbour. Any benefit to Fidelity would be shared across the industry.','US Department of Labor, EBSA',DOL,'2025-05-28','Counter-evidence: general rule, neutral stance','Page text reviewed')],
 'Narrow review. Not obtained: FEC/OpenSecrets and LDA lobbying data for Fidelity or Johnson (OpenSecrets was not fetchable), the Axios article (403), any Fidelity filing on the rescission, and any evidence of Johnson\'s own contact with officials. Fidelity corporate lobbying is not attributed to Johnson. Not exoneration.')

CSGA='https://www.securitymagazin.cz/english/csg-czech-ammunition-initiative-1404072521.html'
LIGA='https://biz.liga.net/en/all/news/czech-billionaire-denies-clash-with-babis-over-weapons-supplies-to-ukraine'
add('michal-strnad','mixed',
 'Strnad owns Czechoslovak Group (CSG), a defence manufacturer whose subsidiaries take part in the Czech-coordinated ammunition initiative for Ukraine and in Slovak framework contracts (earlier profile). Reviewed reporting shows (a) an August 2024 allegation by a Czech senator, reported by Security Magazin, that a CSG subsidiary\'s price per shell was above comparable offers, disputed by CSG and the Czech defence ministry; and (b) December 2025 reporting that incoming Prime Minister Babis had criticised profit from war and promised to scrutinise procurements, while Strnad said there was no conflict. These show a defence supplier dependent on state procurement and in contact with a changing political leadership; they do not show that Strnad obtained a preferential term through public power, and the pricing claim is unadjudicated. No rubric.',
 'Public defence procurement through a government-coordinated initiative; preferential terms or personal exchange not established; price comparison contested',
 'Czech ammunition initiative 2024; Czech government change late 2025',
 [r('Security Magazin (29 Aug 2024): CSG companies participate in the Czech Ammunition Initiative, coordinated by the Czech Ministry of Defence. Senator Lukas Wagenknecht published a 12-page report alleging a contract by CSG subsidiary Excalibur Army was wasteful; the article compares EUR 3,200 per 155mm shell for Excalibur against roughly EUR 2,300-2,950 for Ukraine\'s direct purchases and a Turkish EXW offer of about EUR 2,500, while noting transport was not included so the comparison is not final. Allegation reported by the outlet from documents it did not independently verify. Strnad is named only as owner.','Security Magazin (Jakub Samek)',CSGA,'2024-08-29','Allegation reported by press (secondary)','Page text reviewed via fetch summary'),
  r('LIGA.net (12 Dec 2025), citing Bloomberg: Strnad said he has no conflict with newly elected PM Andrej Babis. Babis had criticised those who profit excessively from war during the campaign and promised to scrutinise procurements. CSG said it will work with any government and hopes the new one joins the initiative after review; the article says the initiative\'s future is in doubt. Ukraine received 3.7 million rounds valued at an estimated EUR 4-4.5 billion.','LIGA.net, citing Bloomberg',LIGA,'2025-12-12','Reported political context and subject\'s statement (secondary)','Page text reviewed via fetch summary')],
 [r('CSG\'s spokesman said the company is transparent with the Ministry of Defence, that prices reflect market levels, logistics and manufacturing costs, and cited the German ministry as saying the price was within range. Defence Minister Jana Cernochova called the senator\'s claims unsubstantiated and out of context.','Security Magazin',CSGA,'2024-08-29','Subject and government responses to allegation','Page text reviewed via fetch summary'),
  r('The relationship with the prime minister is described as critical and uncertain rather than favourable; no source reviewed shows donations, appointments or terms granted to Strnad personally.','LIGA.net',LIGA,'2025-12-12','Counter-evidence: no favourable-treatment finding','Page text reviewed via fetch summary')],
 'Narrow review. Not obtained: the Wagenknecht report, Handelsblatt original, ministry contract terms, Czech campaign-finance or lobbying records, and outcomes of any audit. The 2025 Slovak framework value (up to EUR 58 billion) is a potential ceiling per the earlier profile. Both pricing sources are secondary. Not exoneration.')

ids={p['id'] for p in json.loads((ROOT/'data/billionaires.json').read_text())['people']}
assert set(P)<=ids
out=dict(supersedes=['abigail-johnson','michal-strnad'],profiles=P,rubrics=R)
(ROOT/'data/review-batches/043.json').write_text(json.dumps(out,ensure_ascii=False,indent=2)+'\n')
